grid = [[1, 2, 3, 4], [3, 4, 1, 2], [2, 1, 4, 3], [4, 3, 2, 1]]   # a 4 x 4 mini Sudoku

def check(name, numbers):
    good = sorted(numbers) == [1, 2, 3, 4]
    print(name, numbers, "OK" if good else "WRONG")
    return good

def verify():
    results = list()
    for r in range(4):
        results.append(check("Row", grid[r]))
    for c in range(4):
        results.append(check("Column", [grid[r][c] for r in range(4)]))
    for r in (0, 2):
        for c in (0, 2):
            results.append(check("Box", [grid[r][c], grid[r][c + 1], grid[r + 1][c], grid[r + 1][c + 1]]))
    return all(results)

print("Solution is correct!" if verify() else "Solution is wrong.")
